// Module definition with parameters
module adder #(
    parameter WIDTH = 8
) (
    input  wire [WIDTH-1:0] a,
    input  wire [WIDTH-1:0] b,
    input  wire              cin,
    output wire [WIDTH-1:0] sum,
    output wire              cout
);

    wire [WIDTH:0] result;
    assign result = {1'b0, a} + {1'b0, b} + {{WIDTH{1'b0}}, cin};
    assign sum  = result[WIDTH-1:0];
    assign cout = result[WIDTH];

endmodule

// Module instantiation by name (preferred style)
module top;
    wire [7:0] a = 8'd15;
    wire [7:0] b = 8'd27;
    wire [7:0] s;
    wire c;

    // Named port connection
    adder #(.WIDTH(8)) u_adder (
        .a    (a),
        .b    (b),
        .cin  (1'b0),
        .sum  (s),
        .cout (c)
    );

    initial begin
        #10;
        $display("Sum = %d, Carry = %b", s, c);
        $finish;
    end
endmodule

// Register module — common pattern
module register #(
    parameter WIDTH = 8,
    parameter RESET_VAL = 0
) (
    input  wire             clk,
    input  wire             rst_n,   // active-low reset
    input  wire             en,
    input  wire [WIDTH-1:0] d,
    output reg  [WIDTH-1:0] q
);
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)  q <= RESET_VAL;
        else if (en) q <= d;
    end
endmodule
