// Combinational logic — sensitive to all inputs
module mux2 (
    input  wire [3:0] a, b,
    input  wire       sel,
    output reg  [3:0] y
);
    always @(*) begin   // @(*) = automatic sensitivity list
        if (sel) y = a;
        else     y = b;
    end
endmodule

// Sequential logic — flip-flop (clocked)
module d_ff (
    input  wire clk, rst_n, d,
    output reg  q
);
    // Asynchronous reset (most common in RTL)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)  q <= 1'b0;  // non-blocking assignment!
        else         q <= d;
    end
endmodule

// Case statement
module decoder (
    input  wire [3:0] sel,
    output reg  [15:0] y
);
    always @(*) begin
        y = 16'b0;    // default: all zeros (prevents latches!)
        case (sel)
            4'd0:  y = 16'h0001;
            4'd1:  y = 16'h0002;
            4'd15: y = 16'h8000;
            default: y = 16'hxxxx;
        endcase
    end
endmodule

// Casez — z and ? match anything
module priority_enc (
    input  wire [7:0] in,
    output reg  [2:0] out
);
    always @(*) begin
        casez (in)
            8'b1???????: out = 3'd7;
            8'b01??????: out = 3'd6;
            8'b001?????: out = 3'd5;
            default:     out = 3'd0;
        endcase
    end
endmodule
```

**Key rule**: Use **non-blocking** `<=` in clocked always blocks. Use **blocking** `=` in combinational always blocks.

