`timescale 1ns / 1ps    // time unit / precision

module tb_adder;
    parameter WIDTH = 8;

    // Signals
    reg  [WIDTH-1:0] a, b;
    reg              cin;
    wire [WIDTH-1:0] sum;
    wire             cout;

    // Instantiate DUT (Device Under Test)
    adder #(.WIDTH(WIDTH)) dut (
        .a(a), .b(b), .cin(cin),
        .sum(sum), .cout(cout)
    );

    integer errors = 0;
    reg [WIDTH:0] expected;

    // Test stimulus
    initial begin
        // Directed tests
        a = 0; b = 0; cin = 0;
        #10;
        if ({cout, sum} !== 9'b0) begin
            $display("FAIL: 0+0+0");
            errors = errors + 1;
        end

        a = 8'hFF; b = 8'h01; cin = 0;
        #10;
        expected = 9'h100;  // 256
        if ({cout, sum} !== expected)
            $display("FAIL: FF+01");

        // Random tests
        repeat(1000) begin
            a   = $random;
            b   = $random;
            cin = $random & 1;
            #10;
            expected = {1'b0, a} + {1'b0, b} + cin;
            if ({cout, sum} !== expected) begin
                $display("FAIL: %d+%d+%d", a, b, cin);
                errors = errors + 1;
            end
        end

        if (errors == 0) $display("ALL PASSED");
        else $display("FAILED: %0d errors", errors);
        $finish;
    end

    // Waveform dump
    initial begin
        $dumpfile("waves.vcd");
        $dumpvars(0, tb_adder);
    end
endmodule
