```verilog
// Two-process FSM (recommended style)
module traffic_light (
    input  wire       clk,
    input  wire       rst_n,
    output reg  [1:0] light   // 00=red, 01=yellow, 10=green
);

    // State encoding
    localparam RED    = 2'd0;
    localparam YELLOW = 2'd1;
    localparam GREEN  = 2'd2;

    reg [1:0] state, next_state;
    reg [3:0] count;

    // PROCESS 1: State register (sequential)
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= RED;
            count <= 0;
        end else begin
            state <= next_state;
            if (state != next_state)
                count <= 0;
            else
                count <= count + 1;
        end
    end

    // PROCESS 2: Next state logic (combinational)
    always @(*) begin
        case (state)
            RED:    next_state = (count == 4'd10) ? GREEN  : RED;
            GREEN:  next_state = (count == 4'd8)  ? YELLOW : GREEN;
            YELLOW: next_state = (count == 4'd2)  ? RED    : YELLOW;
            default: next_state = RED;
        endcase
    end

    // Output logic (combinational, based on state)
    always @(*) begin
        case (state)
            RED:    light = 2'b00;
            GREEN:  light = 2'b10;
            YELLOW: light = 2'b01;
            default: light = 2'b00;
        endcase
    end

endmodule
```

**Best practices**: default assignments prevent latches, always use non-blocking `<=` in sequential blocks, separate next-state and output logic into different processes.

